// Parse trigger payload + light debounce.
// Caller posts { reason, app?, story?, force? } — reason je free-form tag.
// Debounce: pokud reason patří do 'post-bg-promote' a není force=true, soft
// rate-limit (caller responsible for spacing). Real persistence vyžaduje
// state store (n8n static data), zde stub.
const body = $input.first().json.body || $input.first().json;
const reason = body.reason || 'unspecified';
const app = body.app || null;
const story = body.story || null;
const force = body.force === true;

return { json: {
  reason,
  app,
  story,
  force,
  ts: new Date().toISOString(),
  // Forward all original fields pro downstream handlers
  trigger_source: body,
}};

// Parse drift report from svc-agent-runner exec output.
// Recipe `system/coolify-drift-check` runs `node scripts/coolify-drift-check.mjs --json`
// and returns stdout JSON in body.output.
const body = $input.first().json.body || $input.first().json;
const raw = body.output || body.stdout || '{}';
let drift;
try {
  drift = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return { json: { error: 'failed to parse drift JSON', raw: String(raw).slice(0, 200) } };
}

// Extract counts
const counts = {
  orphaned: (drift.orphaned || []).length,
  missing: (drift.missing || []).length,
  composeDrift: (drift.composeDrift || []).length,
  serverDrift: (drift.serverDrift || []).length,
};
const total = counts.orphaned + counts.missing + counts.composeDrift + counts.serverDrift;

// Severity classification
let severity = 'clean';
if (counts.orphaned > 0) severity = 'security_concern';
else if (counts.serverDrift > 0) severity = 'critical';
else if (counts.missing > 0) severity = 'high';
else if (counts.composeDrift > 0) severity = 'medium';

// Carry forward trigger context
const triggerCtx = $('parse-trigger').first().json;
return { json: { drift, counts, total, severity, ts: new Date().toISOString(), trigger: triggerCtx } };

// Security concern: orphaned apps in Coolify (manuálně přidané, nejsou v gitu).
// MAY indicate compromise — escalate to operator, NEVER auto-delete.
const d = $input.first().json;
return { json: {
  action_taken: 'security_alert',
  channel: '#aisha-security',
  severity: 'high',
  triggered_by: d.trigger?.reason || 'unspecified',
  message: `${d.counts.orphaned} orphaned Coolify app(s) detected — manuálně přidané, nejsou v gitu manifestu`,
  apps: (d.drift.orphaned || []).map(a => a.name),
  recommendation: 'Audit each app — pokud legitimní, přidat do aisha.manifest. Pokud ne, smazat přes Coolify UI.',
}};

// Critical: server drift (app na špatném serveru). Manual ops needed (server
// migration v Coolify je destruktivní). Alert operator.
const d = $input.first().json;
return { json: {
  action_taken: 'critical_alert',
  channel: '#aisha-deploy-alerts',
  severity: 'critical',
  triggered_by: d.trigger?.reason || 'unspecified',
  message: `${d.counts.serverDrift} app(s) on wrong server — vyžaduje manual migration`,
  drifts: d.drift.serverDrift,
}};

// Clean / extra (no drift) — log only.
const d = $input.first().json;
return { json: {
  action_taken: 'log_only',
  total: d.total,
  severity: d.severity,
  triggered_by: d.trigger?.reason || 'unspecified'
}};
